"""
mission_store.py
────────────────
Single global object that holds the current mission state.
All routes import `store` and read/write it directly.
"""

from dataclasses import dataclass
from typing import Optional
import paramiko
from models import TelemetrySnapshot


@dataclass
class MissionStore:
    # Generated by sage_ai.py
    script:  Optional[str]  = None
    summary: Optional[str]  = None
    phases:  Optional[list] = None

    # Runtime state
    is_executing:     bool                         = False
    ssh_client:       Optional[paramiko.SSHClient] = None
    latest_telemetry: Optional[TelemetrySnapshot]  = None

    def clear(self):
        self.script = self.summary = self.phases = None
        self.is_executing = False
        self.ssh_client = None
        self.latest_telemetry = None

    def has_mission(self) -> bool:
        return self.script is not None


store = MissionStore()
